#include <cstdio>
#include <string>
#include <vector>
#include <queue>
#include <cmath>
#include <ctime>
#include <stack>
#include <map>
#include <set>

using namespace std;

#define pb push_back
#define ppb pop_back
#define mp make_pair
#define fs first
#define sc second
#define abs(a) ((a) < 0 ? -(a) : (a))
#define sqr(a) ((a) * (a))

typedef unsigned int uint;
typedef long long ll;
typedef unsigned long long ull;

const double eps = 1e-9;
const int mod = (int)1e+9 + 7;
const double pi = acos(-1.);
const int maxn = 1000100;

int snm[maxn];
int sz[maxn];

int getroot(int u) {
	return(snm[u] == u ? u : (snm[u] = getroot(snm[u])));
}

void merge(int u, int v) {
	u = getroot(u), v = getroot(v);
	if(u != v) {
		sz[u] += sz[v];
		snm[v] = u;
	}
}

int isok(ll a, ll b, ll p) {
	ll res = 1;
	while(b) {
		if(b & 1) {
			res = res * a % p;
		}
		a = a * a % p;
		b >>= 1;
	}
	return(res == 1 ? p : 1);
}

int binpow(ll a, ll b) {
	ll res = 1;
	while(b) {
		if(b & 1) {
			res = res * a % mod;
		}
		a = a * a % mod;
		b >>= 1;
	}
	return(res);
}

int main() {

	#ifdef SOL
	{
//		freopen("input.txt", "r", stdin);
//		freopen("output.txt", "w", stdout);
	}
	#else
	{
		srand(time(0));
		const string file = "";
		if(!file.empty()) {
			freopen((file + ".in").c_str(), "r", stdin);
			freopen((file + ".out").c_str(), "w", stdout);
		}
	}
	#endif

	int p, k;
	scanf("%d%d", &p, &k);

	if(k == 0) {
		cout << binpow(p, p - 1);
		return(0);
	}

	for(int i = 0; i < p; i++) {
		snm[i] = i;
		sz[i] = 1;
	}

	for(int i = 0; i < p; i++) {
		merge((k * 1ll * i) % p, i);
	}
	ll ans = 1;
	for(int i = 0; i < p; i++) {
		if(getroot(i) == i) {
			ans = (ans * 1ll * isok(k, sz[i], p)) % mod;
		}
	}

	printf("%lld", ans);

	#ifdef SOL
	{
		fflush(stdout);
		fprintf(stderr, "%.3lf ms\n", 1000. * clock() / CLOCKS_PER_SEC);
		fflush(stderr);
	}
	#endif
	return(0);
}

